<script lang="ts">
 import { requests } from '$lib/stores/requests';
 import type { DirectRequestView } from '$lib/request-types';
 let { view, title='Message request', onOpenConversation, onViewInvitation }: { view:DirectRequestView; title?:string; onOpenConversation:(id:string)=>void; onViewInvitation:(id:string)=>void }=$props();
 let incoming=$derived(view.consent==='incomingPending');
 let ready=$derived(view.preview?.type==='ready'?view.preview:null);
</script>
<section class="request-detail" aria-label="Encrypted message request">
 <button class="back" onclick={()=>requests.showInbox()}>← Message requests</button>
 <header><span class="avatar" aria-hidden="true">{incoming?'↙':'↗'}</span><p class="eyebrow">{view.consent==='accepted'?'ACCEPTED CONVERSATION':incoming?'WANTS TO CHAT WITH YOU':'YOUR INTRODUCTION'}</p><h1>{title}</h1><p>{incoming?'You can read this message without accepting the conversation.':view.consent==='outgoingPending'?'Request sent. You can send another message after acceptance.':view.consent==='closed'?'This request is closed.':'Your first message stays in the same conversation.'}</p></header>
 {#if $requests.notice}<p class="notice" role="status">{$requests.notice}</p>{/if}
 {#if $requests.error}<p class="notice error" role="alert">{$requests.error}</p>{/if}
 {#if ready}<article class="intro" aria-label="Decrypted introduction"><p>{ready.text}</p><footer>End-to-end encrypted introduction</footer></article>
 {#if ready.invitation}<div class="invitation"><strong>Group invitation</strong><p>This note is linked to a separate invitation. Accepting this direct conversation does not join the group.</p><button onclick={()=>onViewInvitation(ready.invitation!.conversationId)}>View group invitation</button></div>{/if}
 {:else}<div class="unavailable"><h2>{view.crypto==='importing'?'Opening encrypted content…':'Content unavailable on this device'}</h2><p>You can still decide whether to accept the conversation. Acceptance does not restore unavailable encryption keys.</p><button disabled={$requests.busy} onclick={()=>requests.refresh(view.conversationId)}>Retry preview</button></div>{/if}
 <div class="actions">{#if incoming}<button disabled={$requests.busy || !view.capabilities.canClose} onclick={()=>requests.close(view.conversationId)}>Decline</button><button disabled={$requests.busy} onclick={()=>requests.block(view.conversationId)}>Block sender</button>{/if}{#if incoming}<button class="primary" disabled={$requests.busy || !view.capabilities.canAccept} onclick={()=>requests.accept(view.conversationId)}>{$requests.busy?'Checking…':'Accept conversation'}</button>{:else if view.consent==='outgoingPending'}<button disabled={$requests.busy || !view.capabilities.canClose} onclick={()=>requests.close(view.conversationId)}>Close request</button>{:else if view.consent==='accepted'}<button class="primary" disabled={!view.capabilities.canSend} onclick={()=>onOpenConversation(view.conversationId)}>Open conversation</button>{/if}<button disabled={$requests.busy} onclick={()=>requests.refresh(view.conversationId)}>Refresh status</button></div>
 {#if incoming || view.consent==='outgoingPending'}<p class="quiet">Replies, reactions, typing, receipts, calls and attachments stay off until acceptance.</p>{/if}
</section>
<style>
.request-detail{max-width:780px;width:100%;margin:auto;padding:36px;overflow:auto}.back{border:0;background:none;padding:0;color:var(--text-secondary);margin-bottom:32px}header{text-align:center}.avatar{display:grid;place-items:center;width:60px;height:60px;border-radius:20px;background:var(--bg-card);border:1px solid var(--border);font-size:28px;color:var(--accent);margin:0 auto 22px}.eyebrow{font-size:10px;letter-spacing:.14em;font-weight:700;color:var(--accent)}h1{font-size:28px;letter-spacing:-.035em;margin:10px 0}header>p:last-child{font-size:14px;line-height:1.6;color:var(--text-secondary);max-width:470px;margin:12px auto 28px}.intro{padding:26px;border:1px solid var(--border);background:var(--bg-secondary);border-radius:16px}.intro>p{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.8;font-size:16px;margin:0;color:var(--text-primary)}.intro footer{font-size:10px;letter-spacing:.04em;color:var(--text-tertiary);margin-top:26px}.actions{display:flex;justify-content:center;gap:12px;margin-top:26px}button{font:inherit;font-size:13px;border:1px solid var(--border);border-radius:9px;background:var(--bg-card);color:var(--text-primary);padding:11px 17px;cursor:pointer}button.primary{background:var(--accent);color:white;border-color:transparent}button:disabled{opacity:.45;cursor:default}.quiet{text-align:center;font-size:12px;line-height:1.6;color:var(--text-tertiary);max-width:440px;margin:22px auto}.notice,.unavailable,.invitation{padding:20px;border:1px solid var(--border);border-radius:14px;margin:20px 0;color:var(--text-secondary);font-size:14px;line-height:1.6}.error{color:#e7958d}.unavailable h2{color:var(--text-primary);font-size:18px}.invitation strong{color:var(--text-primary)}@media(max-width:600px){.request-detail{padding:24px 18px}h1{font-size:24px}.intro{padding:20px}.actions{flex-wrap:wrap}}
</style>
